def scenario_block(state: dict) -> str:
    """Сценарий для промпта: цели всех актов, подробности текущего, NPC, монстры, тайна."""
    sc = SCENARIOS.get(state.get("scenario") or "")
    if not sc:
        return ""
    act = state.get("act", 1)
    lines = [f"СЦЕНАРИЙ «{sc['title']}» (это знает только ведущий, игрокам не пересказывай)."]
    if sc.get("level"):
        lines.append(f"Рекомендуемый уровень группы: {sc['level']}. Подбирай число и состав врагов под фактический уровень и размер группы; не выставляй весь список монстров одновременно.")
    for i, a in enumerate(sc["acts"], 1):
        mark = "▶ ТЕКУЩИЙ" if i == act else ("пройден" if i < act else "впереди")
        lines.append(f"Акт {i} [{mark}]: {a['title']} — цель: {a['goal']}")
        if i == act:
            lines.append(f"  Подробности акта: {a['details']}")
    lines.append("NPC: " + "; ".join(sc["npcs"]))
    lines.append("Монстры сценария (для start_combat): " + ", ".join(f"{ru} = {idx}" for ru, idx in sc["monsters"]))
    lines.append(f"Тайна (раскрывай постепенно, к последним актам): {sc['twist']}")
    lines.append(f"Возможные финалы: {sc['endings']}")
    if sc.get("rewards"):
        lines.append(f"Награды и последствия: {sc['rewards']}. Выдавай награды только если герои заслужили их действиями; не превращай их в гарантированный лут при провале.")
    if state.get("plot_notes"):
        lines.append("Заметки ведущего по сюжету: " + "; ".join(state["plot_notes"][-12:]))
    lines.append("Сценарий — канва, а не рельсы: если игроки уходят в сторону, импровизируй и мягко возвращай к цели акта. "
                 "Когда цель акта достигнута — вызови advance_plot.")
    return "\n".join(lines)
